window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-c8cb4423cf972e92"]={"versions": [{"id": "FIG-c8cb4423cf972e92", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (<code>sd E2E_Sender I-PDU</code>) zur Darstellung des Sender-Ablaufs auf I-PDU-Ebene in der AUTOSAR Classic Platform. Das Diagramm illustriert das Zusammenspiel zwischen einem I-PDU-Sender, der AUTOSAR E2E Library, der CRC Library und dem PDU Router (PduR).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Sender of I-PDUs:</strong> Senderkomponente (z. B. COM-Modul oder SW-C), die die I-PDU zusammenstellt und absendet.\n</li><li><strong>E2E Library:</strong> Bibliothek für End-to-End-Schutzfunktionen mit der Schnittstelle <code>E2E_PXXProtect(Config, State, Data)</code>.\n</li><li><strong>CRC Library:</strong> Hilfsbibliothek zur Prüfsummenberechnung über <code>Crc_CalculateCRCx()</code>.\n</li><li><strong>«module» PduR:</strong> PDU-Router-Basissoffware-Modul mit der Schnittstelle <code>PduR_ComTransmit(ComTxPduId, PduInfoPtr)</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Initialisierung:</strong> Beim Start des Senders (<code>[At Sender startup]</code>) instanziiert und initialisiert dieser die <code>Config</code>- und <code>State</code>-Strukturen.\n</li><li><strong>Datenbereitstellung:</strong> Der Sender aktualisiert die I-PDU mit aktuellen Signalwerten (<code>Update I-PDU with fresh values from signals</code>) und castet bzw. referenziert die Daten (<code>Data = (uint8*) I-PDU</code>).\n</li><li><strong>E2E-Schutz:</strong> Der Sender ruft synchron <code>E2E_PXXProtect(Config, State, Data)</code> auf der <code>E2E Library</code> auf.\n</li><li><strong>Bibliotheksinterne Ausführung:</strong>\n<ul class=\"fig-list\"><li>Die E2E Library führt ihre Logik aus (z. B. Inkrementieren des Counters).\n</li><li>Bei E2E Profile 1 und 2 nutzt sie <code>Crc_CalculateCRCx()</code>, um die CRC über DataID und Daten zu berechnen.\n</li><li>Sie schreibt die aktualisierten Steuerfelder (CRC, Counter) in <code>Data</code>.\n</li></ul>\n</li><li><strong>Rückmeldung &amp; Fehlerbehandlung:</strong> Die Funktion liefert den Status <code>ret</code> an den Sender zurück, welcher den Rückgabewert auswertet und interne Fehler behandelt (z. B. Meldung an das DEM).\n</li><li><strong>Transmission:</strong> Der Sender initiiert die Übertragung über den PduR mittels <code>PduR_ComTransmit(ComTxPduId, PduInfoPtr)</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Sequenzdiagramm dient als Implementierungs- und Integrationsleitfaden für Software-Komponenten oder BSW-Module, die I-PDUs mittels der E2E-Bibliothek absichern. Wesentliche Aspekte:</p>\n<ul class=\"fig-list\"><li>Die Lebensdauer und Initialisierung der Zustand- (<code>State</code>) und Konfigurationsstrukturen (<code>Config</code>) obliegt der aufrufenden Sender-Einheit.\n</li><li>Vor dem Schutzaufruf muss das I-PDU-Datenfeld im Speicher als Byte-Array (<code>uint8*</code>) bereitstehen.\n</li><li>Der Aufrufer ist verpflichtet, den Rückgabewert <code>ret</code> der Schutzfunktion zu prüfen und Fehlerzustände an das Diagnose-Event-Management (DEM) weiterzuleiten, bevor die PDU an die unterlagerte Schicht (<code>PduR</code>) übergeben wird.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-d2eb5d37159deec5", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Darstellung des Sender-Ablaufs auf I-PDU-Ebene in der AUTOSAR Classic Platform. Das Diagramm illustriert das Zusammenspiel zwischen einem I-PDU-Sender, der AUTOSAR E2E Library, der CRC Library und dem PDU Router (PduR).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Sender of I-PDUs:</strong> Senderkomponente, die die I-PDU zusammenstellt und absendet.\n</li><li><strong>E2E Library:</strong> Bibliothek für End-to-End-Schutzfunktionen mit der Schnittstelle <code>E2E_PXXProtect(Config, State, Data)</code>.\n</li><li><strong>CRC Library:</strong> Hilfsbibliothek zur Prüfsummenberechnung über <code>Crc_CalculateCRCx()</code>.\n</li><li><strong>«module» PduR:</strong> PDU-Router-Basissoffware-Modul mit der Schnittstelle <code>PduR_ComTransmit</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Initialisierung:</strong> Beim Start des Senders (<code>[At Sender startup]</code>) instanziiert und initialisiert dieser die <code>Config</code>- und <code>State</code>-Strukturen.\n</li><li><strong>Datenbereitstellung:</strong> Der Sender aktualisiert die I-PDU mit aktuellen Signalwerten (<code>Update I-PDU with fresh values from signals</code>) und referenziert die Daten (<code>Data = (uint8*) I-PDU</code>).\n</li><li><strong>E2E-Schutz:</strong> Der Sender ruft synchron <code>E2E_PXXProtect(Config, State, Data)</code> auf der <code>E2E Library</code> auf.\n</li><li><strong>Bibliotheksinterne Ausführung:</strong>\n<ul class=\"fig-list\"><li>Die E2E Library führt ihre Logik aus (z. B. Inkrementieren des Counters).\n</li><li>Bei E2E Profile 1 und 2 nutzt sie <code>Crc_CalculateCRCx()</code>, um die CRC über DataID und Daten zu berechnen (mit eigenem Aktivierungsbalken auf der CRC-Lebenslinie).\n</li><li>Sie schreibt die aktualisierten Steuerfelder (CRC, Counter) in <code>Data</code>.\n</li></ul>\n</li><li><strong>Rückmeldung &amp; Fehlerbehandlung:</strong> Die Funktion liefert den Status <code>ret</code> an den Sender zurück, welcher den Rückgabewert auswertet und interne Fehler behandelt (z. B. Meldung an das DEM).\n</li><li><strong>Transmission:</strong> Der Sender initiiert die Übertragung über den PduR mittels <code>PduR_ComTransmit</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Sequenzdiagramm dient als Implementierungs- und Integrationsleitfaden für Software-Komponenten oder BSW-Module, die I-PDUs mittels der E2E-Bibliothek absichern. Wesentliche Aspekte:</p>\n<ul class=\"fig-list\"><li>Die Lebensdauer und Initialisierung der Zustand- (<code>State</code>) und Konfigurationsstrukturen (<code>Config</code>) obliegt der aufrufenden Sender-Einheit.\n</li><li>Vor dem Schutzaufruf muss das I-PDU-Datenfeld im Speicher als Byte-Array (<code>uint8*</code>) bereitstehen.\n</li><li>Der Aufrufer ist verpflichtet, den Rückgabewert <code>ret</code> der Schutzfunktion zu prüfen und Fehlerzustände an das Diagnose-Event-Management (DEM) weiterzuleiten, bevor die PDU an die unterlagerte Schicht (<code>PduR</code>) übergeben wird.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-c8cb4423cf972e92", "to": "FIG-d2eb5d37159deec5", "fr": "R3.2.3", "tr": "R4.1.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><strong>UML-Rahmen:</strong> Der Diagrammrahmen mit dem Sequenzkopf <code>sd E2E_Sender I-PDU</code> wurde entfernt.\n</li><li><strong>Schnittstellenaufruf PduR:</strong> Der Aufruf <code>PduR_ComTransmit(ComTxPduId, PduInfoPtr)</code> wurde zu <code>PduR_ComTransmit</code> vereinfacht (Wegfall der Parameterdarstellung).\n</li><li><strong>Komponentenbeschriftung:</strong> Das Stereotyp-Symbol (zwei Kreise mit Verbindungssteg) unterhalb von <code>PduR</code> im Modulkopf wurde entfernt.\n</li><li><strong>Lebenslinie:</strong> An der Lebenslinie der <code>CRC Library</code> wurde beim Aufruf zur CRC-Berechnung ein expliziter Aktivierungsbalken ergänzt.\n</li></ul>"}]};
